/** How long the reminder ask's answer stays on screen before Today: long enough to read one line. */
export const REMIND_RESULT_MS = 1400;

/** The reminder's own copy (`reminder.body`), as the drawn notification's title and line. */
export function reminderPreview(body: string): { title: string; line: string } {
  const cut = body.indexOf('. ');
  if (cut < 0) return { title: body, line: '' };
  return { title: body.slice(0, cut), line: body.slice(cut + 2) };
}
